INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (126401, 1, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 1, 2, 1.47, 0.0, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", -470.0, "クローチェ", 1, 10001, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (126401, 2, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 1, 1, 2.15, 0.0, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", -470.0, "クローチェ", 2, 10002, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (126501, 1, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 1, 2, 0.0, 0.0, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", -470.0, "ライラエル", 2, 10003, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (126501, 2, "2023/06/30 12:00:00", "2023/09/22 14:59:59", 1, 1, 0.0, 0.0, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", -470.0, "ライラエル", 1, 10004, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (127702, 1, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 2, 2, 0.0, 0.0, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", -470.0, "リンド", 2, 10005, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (127702, 2, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 2, 2, 0.0, 0.0, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", -470.0, "リンド", 2, 10006, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (127802, 1, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 2, 1, 0.0, 0.0, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", -470.0, "ヴルム", 1, 10007, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (127802, 2, "2023/09/15 15:00:00", "2023/12/22 14:59:59", 2, 1, 6.5, 0.0, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", -470.0, "ヴルム", 2, 10008, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (129602, 1, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 3, 1, 0.0, 0.0, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", -470.0, "アネモネ", 2, 10009, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (129602, 2, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 3, 1, 0.0, 0.0, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", -470.0, "アネモネ", 2, 10010, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (129701, 1, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 3, 1, 0.0, 0.0, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", -470.0, "ネフィ=ネラ", 1, 10011, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (129701, 2, "2023/12/15 15:00:00", "2024/03/22 14:59:59", 3, 1, 6.2, 0.0, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", -470.0, "ネフィ=ネラ", 2, 10012, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130301, 1, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 4, 5, 3.1, 0.0, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", -470.0, "カノン", 3, 10013, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130301, 2, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 4, 2, 6.15, 0.0, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", -470.0, "カノン", 3, 10014, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130401, 1, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 4, 2, 0.0, 0.0, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", -470.0, "ナーナ", 2, 10015, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130401, 2, "2024/03/15 15:00:00", "2024/06/22 14:59:59", 4, 1, 3.35, 0.0, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", -470.0, "ナーナ", 2, 10016, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130502, 1, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 5, 1, 0.0, 0.0, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", -470.0, "ホウオウ", 1, 10017, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130502, 2, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 5, 1, 3.18, 0.0, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", -470.0, "ホウオウ", 2, 10018, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130503, 3, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 5, 4, 0.0, 0.0, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", -470.0, "ホウオウ", 4, 10019, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (123301, 1, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 5, 2, 4.9, 0.0, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", -470.0, "ネア", 1, 10020, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (123301, 2, "2024/06/15 15:00:00", "2024/09/22 14:59:59", 5, 2, 4.8, 0.0, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", -470.0, "ネア", 1, 10021, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133301, 1, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 6, 1, 4.922, 0.0, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", -470.0, "カリザ", 3, 10022, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133301, 2, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 6, 5, 9.638, 0.0, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", -470.0, "カリザ", 3, 10023, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133401, 1, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 6, 2, 2.88, 0.0, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", -470.0, "ミーア", 1, 10024, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133401, 2, "2024/09/15 15:00:00", "2024/12/22 14:59:59", 6, 1, 4.818, 0.0, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", -470.0, "ミーア", 5, 10025, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133002, 1, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 7, 1, 1.78, 0.0, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", -470.0, "グレイス", 2, 10026, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133002, 2, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 7, 7, 6.15, 0.0, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", -470.0, "グレイス", 1, 10027, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133102, 1, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 7, 2, 4.28, 0.0, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", -470.0, "ヴァイオレット", 6, 10028, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (133102, 2, "2024/12/15 15:00:00", "2025/03/22 14:59:59", 7, 1, 0.0, 0.0, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", -470.0, "ヴァイオレット", 1, 10029, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (136902, 1, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 8, 1, 5.53, 0.0, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", -470.0, "ルルィ", 2, 10030, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (136902, 2, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 8, 7, 6.05, 0.0, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", -470.0, "ルルィ", 9, 10031, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (137001, 1, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 8, 1, 0.0, 0.0, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", -470.0, "デュラン", 2, 10032, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (137001, 2, "2025/03/15 15:00:00", "2025/06/23 14:59:59", 8, 1, 0.0, 0.0, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", -470.0, "デュラン", 2, 10033, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (135902, 1, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 9, 2, 0.0, 0.0, "おう\n好きなもん持ってきな", -470.0, "サツキ", 2, 10034, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (135902, 2, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 9, 6, 4.935, 0.0, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", -470.0, "サツキ", 1, 10035, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (135802, 1, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 9, 5, 7.441, 0.0, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", -470.0, "ユキノ", 2, 10036, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (135802, 2, "2025/06/16 15:00:00", "2025/09/23 14:59:59", 9, 7, 0.0, 0.0, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", -470.0, "ユキノ", 7, 10037, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130901, 1, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 10, 2, 2.295, 0.0, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", -470.0, "クルル", 2, 10038, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (130901, 2, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 10, 6, 6.281, 0.0, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", -470.0, "クルル", 1, 10039, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (137701, 1, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 10, 1, 5.549, 0.0, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", -470.0, "ヴォルガーノ", 2, 10040, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (137701, 2, "2025/09/16 15:00:00", "2025/12/22 14:59:59", 10, 6, 2.64, 0.0, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", -470.0, "ヴォルガーノ", 3, 10041, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (132801, 1, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 11, 4, 7.642, 0.0, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", -470.0, "ライラエル", 7, 10042, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (132802, 2, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 11, 1, 0.0, 0.0, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", -470.0, "ライラエル", 1, 10043, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (134502, 1, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 11, 1, 0.0, 0.0, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", -470.0, "クローチェ", 1, 10044, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (134501, 2, "2025/12/15 15:00:00", "2026/03/23 11:59:59", 11, 1, 3.72, 0.0, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", -470.0, "クローチェ", 2, 10045, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (138201, 1, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 12, 1, 4.991, 0.0, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", -470.0, "ネフィ＝ネラ", 2, 10046, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (138201, 2, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 12, 4, 3.877, 0.0, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", -470.0, "ネフィ＝ネラ", 1, 10047, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (136001, 1, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 12, 6, 1.71, 0.0, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", -470.0, "アラクネ", 4, 10048, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (136001, 2, "2026/03/16 12:00:00", "2026/06/22 11:59:59", 12, 2, 5.32, 0.0, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", -470.0, "アラクネ", 5, 10049, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (135401, 1, "2026/06/15 12:00:00", "2026/09/22 11:59:59", 13, 4, 3.727, 0.0, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", -470.0, "アネモネ", 9, 10050, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (135401, 2, "2026/06/15 12:00:00", "2026/09/22 11:59:59", 13, 9, 7.213, 0.0, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", -470.0, "アネモネ", 7, 10051, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (135301, 1, "2026/06/15 12:00:00", "2026/09/22 11:59:59", 13, 2, 1.874, 0.0, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", -470.0, "クリア", 1, 10052, 2002);
